"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2471],{26885:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a cooldown of `cooldown` seconds.\\n\\nA new cooldown starts ready \u2014 the first [Cooldown:check] passes without waiting.","params":[{"name":"cooldown","desc":"Seconds between allowed actions","lua_type":"number"}],"returns":[{"desc":"","lua_type":"CooldownType"}],"function_type":"static","source":{"line":47,"path":"src/Shared/Class/Cooldown.luau"}},{"name":"check","desc":"Returns whether enough time has passed for the action to run again.\\n\\nChecking does not consume the cooldown \u2014 call [Cooldown:reset] yourself once you\\nactually perform the action, or it will never start.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":65,"path":"src/Shared/Class/Cooldown.luau"}},{"name":"reset","desc":"Starts the cooldown, blocking [Cooldown:check] for `cooldown` seconds from now.","params":[],"returns":[],"function_type":"method","source":{"line":75,"path":"src/Shared/Class/Cooldown.luau"}}],"properties":[],"types":[],"name":"Cooldown","desc":"A rate limiter you check before an action and reset after it.\\n\\nTiming uses `Workspace:GetServerTimeNow()`, which is synchronised between the\\nserver and every client, so the same Cooldown logic behaves identically on both\\nsides.\\n\\n```lua\\nlocal fireCooldown = Cooldown.new(0.5)\\n\\nif fireCooldown:check() then\\n\\tfireCooldown:reset()\\n\\tfireWeapon()\\nend\\n```\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":22,"path":"src/Shared/Class/Cooldown.luau"}}')}}]);